CREATE TABLE pin_leases (id TEXT NOT NULL PRIMARY KEY, owner_object_id TEXT NOT NULL, source TEXT NOT NULL, policy_id TEXT NOT NULL, provider_mode TEXT NOT NULL, content_mode TEXT NOT NULL, created_at @TZ@ NOT NULL, last_touched_at @TZ@ NOT NULL, expires_at @TZ@ NOT NULL, generation BIGINT NOT NULL, state TEXT NOT NULL, FOREIGN KEY(owner_object_id) REFERENCES objects(id) ON DELETE CASCADE, CHECK(state IN ('active','expired','cancelled','evicted')));
CREATE TABLE pin_lease_targets (id TEXT NOT NULL PRIMARY KEY, lease_id TEXT NOT NULL, cid TEXT NOT NULL, logical_size BIGINT NOT NULL, provider TEXT NOT NULL, state TEXT NOT NULL, created_at @TZ@ NOT NULL, last_touched_at @TZ@ NOT NULL, FOREIGN KEY(lease_id) REFERENCES pin_leases(id) ON DELETE CASCADE, CHECK(state IN ('waiting','submitted','pinned','degraded','quota_waiting','quota_blocked','evicted','released')));
CREATE TABLE remote_pins (provider TEXT NOT NULL, cid TEXT NOT NULL, request_id TEXT, cid_size BIGINT NOT NULL, status TEXT NOT NULL, epoch BIGINT NOT NULL, failure_attempts INTEGER NOT NULL DEFAULT 0, next_retry_at @TZ@, last_failed_request_id TEXT, last_touched_at @TZ@ NOT NULL, last_error_class TEXT, last_error_text TEXT, CONSTRAINT pk_remote_pins PRIMARY KEY(provider,cid), CHECK(status IN ('reserved','queued','pinning','pinned','failed','absent')), CHECK(epoch>=1), CHECK(failure_attempts>=0));
CREATE TABLE pin_jobs (id TEXT NOT NULL PRIMARY KEY, operation TEXT NOT NULL, provider TEXT NOT NULL, cid TEXT NOT NULL, lease_id TEXT, target_id TEXT, expected_generation BIGINT, expected_remote_epoch BIGINT, state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at @TZ@ NOT NULL, locked_until @TZ@, submit_phase TEXT DEFAULT 'ready', last_error TEXT, created_at @TZ@ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at @TZ@ NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(state IN ('pending','running','done')), CHECK(((operation IN ('submit','poll') AND lease_id IS NOT NULL AND target_id IS NOT NULL AND expected_generation IS NOT NULL AND expected_remote_epoch IS NULL) OR (operation IN ('unpin','reconcile') AND lease_id IS NULL AND target_id IS NULL AND expected_generation IS NULL AND expected_remote_epoch IS NOT NULL))), CHECK(((operation='submit' AND submit_phase IS NOT NULL AND submit_phase IN ('ready','calling','recovering','recovery_backoff')) OR (operation<>'submit' AND submit_phase IS NULL))));
CREATE TABLE pin_provider_usage (provider TEXT NOT NULL PRIMARY KEY, reserved_bytes BIGINT NOT NULL DEFAULT 0, reserved_pins BIGINT NOT NULL DEFAULT 0, observed_bytes BIGINT, observed_pins BIGINT, observed_at @TZ@);
CREATE UNIQUE INDEX uq_pin_leases_owner_object_source ON pin_leases(owner_object_id,source);
CREATE UNIQUE INDEX uq_pin_lease_targets_lease_cid_provider ON pin_lease_targets(lease_id,cid,provider);
CREATE INDEX idx_pin_jobs_state_next_attempt_locked ON pin_jobs(state,next_attempt_at,locked_until);
CREATE INDEX idx_remote_pins_provider_last_touched ON remote_pins(provider,last_touched_at);
CREATE INDEX idx_pin_lease_targets_provider_cid_state ON pin_lease_targets(provider,cid,state);
CREATE INDEX idx_pin_leases_state_expires ON pin_leases(state,expires_at);
CREATE TABLE pin_submit_history (job_id TEXT NOT NULL PRIMARY KEY, api TEXT NOT NULL, strategy TEXT NOT NULL, effect TEXT NOT NULL, state TEXT NOT NULL, first_error TEXT, last_error TEXT, submit_calls INTEGER NOT NULL DEFAULT 0, recovery_queries INTEGER NOT NULL DEFAULT 0, started_at @TZ@ NOT NULL, correlation TEXT);
CREATE TABLE pin_invocation_routes (job_id TEXT NOT NULL PRIMARY KEY, route TEXT NOT NULL, remote_epoch BIGINT NOT NULL);
CREATE TABLE pin_resource_history (provider TEXT NOT NULL, cid TEXT NOT NULL, epoch BIGINT NOT NULL, ledger TEXT NOT NULL, PRIMARY KEY(provider,cid,epoch));
CREATE TABLE pin_provider_routes (provider TEXT NOT NULL PRIMARY KEY, snapshot TEXT NOT NULL, display_name TEXT NOT NULL, retired BOOLEAN NOT NULL);
CREATE TABLE remote_pin_ledger (provider TEXT NOT NULL, cid TEXT NOT NULL, route TEXT, ownership TEXT NOT NULL, effect TEXT NOT NULL, first_observed_at @TZ@, last_observed_at @TZ@, remote_pinned_at @TZ@, gateway_verified_at @TZ@, content_verified_at @TZ@, first_error TEXT, last_error TEXT, PRIMARY KEY(provider,cid));
CREATE TABLE pin_extension_decisions (version_row_id TEXT PRIMARY KEY NOT NULL, object_id TEXT NOT NULL REFERENCES objects(id) ON DELETE CASCADE, control_revision TEXT NOT NULL UNIQUE, config_revision TEXT NOT NULL, effect TEXT NOT NULL CHECK(effect IN ('accepted','skipped','no_intent')), snapshot TEXT NOT NULL, CONSTRAINT ck_pin_extension_decisions_revision CHECK(length(config_revision)=64), CONSTRAINT fk_pin_extension_decisions_owner FOREIGN KEY(version_row_id,object_id) REFERENCES object_versions(id,object_id) ON DELETE CASCADE);
CREATE TABLE pin_submit_observations (id TEXT NOT NULL PRIMARY KEY, job_id TEXT NOT NULL, provider TEXT NOT NULL, expected_cid TEXT NOT NULL, route TEXT NOT NULL, effect TEXT NOT NULL, resources TEXT NOT NULL, outcome TEXT NOT NULL, submit_call INTEGER NOT NULL, remote_epoch BIGINT NOT NULL, claim_until @TZ@ NOT NULL, started_at @TZ@ NOT NULL, observed_at @TZ@, safe_error TEXT, needs_attention BOOLEAN NOT NULL);
CREATE INDEX pin_submit_observation_domain_debt ON pin_submit_observations(provider,needs_attention);
CREATE UNIQUE INDEX pin_submit_observation_job ON pin_submit_observations(job_id,submit_call);
CREATE INDEX pin_submit_observation_resource ON pin_submit_observations(provider,expected_cid);
CREATE TABLE pin_lease_requirements (lease_id TEXT NOT NULL PRIMARY KEY, owner_object_id TEXT NOT NULL, contract TEXT NOT NULL, created_at @TZ@ NOT NULL);
CREATE TABLE pin_replica_observations (sequence @SEQUENCE@, job_id TEXT NOT NULL, provider TEXT NOT NULL, expected_cid TEXT NOT NULL, route TEXT NOT NULL, phase TEXT NOT NULL, resources TEXT NOT NULL, outcome TEXT NOT NULL, remote_epoch BIGINT NOT NULL, expected_generation BIGINT, lease_id TEXT, target_id TEXT, safe_error TEXT, claim_until @TZ@ NOT NULL, observed_at @TZ@ NOT NULL, projectable BOOLEAN NOT NULL);
CREATE INDEX pin_replica_scope_lifetime ON pin_replica_observations(provider,expected_cid,sequence);
